function hasTwoRisingRuns(nums: number[], k: number): boolean {
  const n = nums.length;
  const run = new Array(n).fill(1);
  for (let i = 1; i < n; i++) if (nums[i] > nums[i - 1]) run[i] = run[i - 1] + 1;
  for (let a = 0; a + 2 * k <= n; a++) {
    if (run[a + k - 1] >= k && run[a + 2 * k - 1] >= k) return true;
  }
  return false;
}

