  let prev = 0, cur = 1;
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > nums[i - 1]) cur++;
    else { prev = cur; cur = 1; }
    if (cur >= 2 * k || Math.min(prev, cur) >= k) return true;
  }
  return false;
}

